#include "tracker_adr.h"
#include "adr_history.h"
void tracker_adr_json(cJSON *lora){lorawan_adr_event_t events[ADR_HISTORY_CAPACITY];uint32_t total=0;size_t n=lorawan_adr_history(events,ADR_HISTORY_CAPACITY,&total);cJSON *j=cJSON_AddObjectToObject(lora,"adr_diagnostics");if(!j)return;cJSON_AddNumberToObject(j,"total",total);cJSON_AddNumberToObject(j,"capacity",ADR_HISTORY_CAPACITY);cJSON *list=cJSON_AddArrayToObject(j,"events");for(size_t i=0;i<n;i++){lorawan_adr_event_t *e=&events[i];cJSON *row=cJSON_CreateObject();if(!row)break;cJSON_AddNumberToObject(row,"id",e->id);cJSON_AddNumberToObject(row,"uptime_ms",e->uptime_ms);cJSON_AddStringToObject(row,"source",e->source==1?"network":"fallback");cJSON_AddNumberToObject(row,"status",e->status);cJSON_AddBoolToObject(row,"adr_enabled",e->enabled);cJSON_AddNumberToObject(row,"commands",e->commands);cJSON_AddNumberToObject(row,"before_dr",e->before_dr);cJSON_AddNumberToObject(row,"requested_dr",e->requested_dr);cJSON_AddNumberToObject(row,"after_dr",e->after_dr);cJSON_AddNumberToObject(row,"before_power_index",e->before_power);cJSON_AddNumberToObject(row,"requested_power_index",e->requested_power);cJSON_AddNumberToObject(row,"after_power_index",e->after_power);cJSON_AddNumberToObject(row,"before_dbm",e->before_dbm);cJSON_AddNumberToObject(row,"after_dbm",e->after_dbm);cJSON_AddNumberToObject(row,"before_repetitions",e->before_repetitions);cJSON_AddNumberToObject(row,"requested_repetitions",e->requested_repetitions);cJSON_AddNumberToObject(row,"after_repetitions",e->after_repetitions);cJSON_AddItemToArray(list,row);}}
